1	// Package store keeps the API's data in memory. It is safe for concurrent use.
2	package store
3	
4	import (
5		"errors"
6		"fmt"
7		"sort"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// Plan is an account's or a customer's subscription plan.
14	type Plan string
15	
16	const (
17		PlanFree Plan = "free"
18		PlanPro  Plan = "pro"
19	)
20	
21	// Valid reports whether p is a known plan.
22	func (p Plan) Valid() bool { return p == PlanFree || p == PlanPro }
23	
24	// Account is one tenant of the product.
25	type Account struct {
26		ID   string
27		Name string
28		Plan Plan
29		// TaxRateBP is the tax rate charged on this account's invoices, in basis points (1% = 100).
30		TaxRateBP int
31	}
32	
33	// Customer is one of an account's customers.
34	type Customer struct {
35		ID        string    `json:"id"`
36		AccountID string    `json:"-"`
37		Name      string    `json:"name"`
38		Email     string    `json:"email"`
39		Plan      Plan      `json:"plan"`
40		CreatedAt time.Time `json:"created_at"`
41	}
42	
43	// LineItem is one line of an invoice.
44	type LineItem struct {
45		Description string `json:"description"`
46		Quantity    int    `json:"quantity"`
47		UnitCents   int64  `json:"unit_cents"`
48	}
49	
50	// Invoice is a bill to a customer.
51	type Invoice struct {
52		ID         string     `json:"id"`
53		AccountID  string     `json:"-"`
54		CustomerID string     `json:"customer_id"`
55		Lines      []LineItem `json:"lines"`
56		// CouponPercent is a percentage discount (0 to 100).
57		CouponPercent int `json:"coupon_percent"`
58		// CreditCents is a fixed amount taken off the invoice.
